<?php declare(strict_types=1); $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><title>Safeguarding governance</title><main><h1>Safeguarding governance register</h1><p>Metadata only. This view never returns reporter identity, subject references, summaries, narratives or specialist notes.</p><?php if($error!==''):?><p role="alert"><?= $e($error) ?></p><?php endif;?><table><thead><tr><th>Reference</th><th>Category</th><th>Severity</th><th>Status</th><th>Assigned</th><th>Legal hold</th><th>Action</th></tr></thead><tbody><?php foreach($cases as $case):?><tr><td><?= $e($case['case_reference']) ?></td><td><?= $e($case['category']) ?></td><td><?= $e($case['severity']) ?></td><td><?= $e($case['status']) ?></td><td><?= $e($case['assigned_specialist_id']) ?></td><td><?= (bool)$case['legal_hold']?'Active':'None' ?></td><td><form method="post" action="/admin/safeguarding/cases/<?= $e($case['id']) ?>/legal-hold<?= (bool)$case['legal_hold']?'/release':'' ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><label>Reason<textarea name="reason" minlength="20" maxlength="1000" required></textarea></label><button><?= (bool)$case['legal_hold']?'Release hold':'Place hold' ?></button></form></td></tr><?php endforeach;?></tbody></table></main>